<?php
/** Orchard Ledger farmer publishing: accountable availability records, quantity amendments, status control, and export evidence. */
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_once __DIR__ . '/../includes/workspace.php';
require_once __DIR__ . '/../includes/marketplace.php';

$farmer = require_role(['farmer']);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $action = normalize_text($_POST['listing_action'] ?? 'publish', 30);
    try {
        if ($action === 'update_status') {
            $listingId = filter_input(INPUT_POST, 'listing_id', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
            if (!$listingId) { throw new RuntimeException('Choose a valid produce record.'); }
            $updatedStatus = update_produce_listing_status((int) $farmer['id'], (int) $listingId, normalize_text($_POST['status'] ?? '', 20));
            flash('success', 'Produce record #' . $listingId . ' is now ' . str_replace('_', ' ', $updatedStatus) . '.');
        } elseif ($action === 'update_quantity') {
            $listingId = filter_input(INPUT_POST, 'listing_id', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
            if (!$listingId) { throw new RuntimeException('Choose a valid produce record.'); }
            $quantity = update_produce_listing_quantity((int) $farmer['id'], (int) $listingId, $_POST['quantity_available'] ?? null);
            flash('success', 'Available quantity for record #' . $listingId . ' is now ' . number_format($quantity, 2) . ' kg.');
        } elseif ($action === 'publish') {
            $listingId = publish_produce_listing((int) $farmer['id'], $_POST);
            flash('success', 'Listing #' . $listingId . ' is now active. Matching default-filter alerts were recorded for eligible accounts.');
        } else { throw new RuntimeException('That listing action is not available.'); }
    } catch (Throwable $exception) { flash('error', $exception instanceof RuntimeException ? $exception->getMessage() : 'The listing action could not be completed.'); }
    redirect('farmer/listings.php');
}

$categories = fetch_all('SELECT id, name FROM produce_categories WHERE is_active = 1 ORDER BY name');
$locations = fetch_all('SELECT id, district, tehsil, area FROM locations ORDER BY district, tehsil, area');
$listings = fetch_all('SELECT pl.*, pc.name AS category_name, l.district FROM produce_listings pl JOIN produce_categories pc ON pc.id = pl.category_id JOIN locations l ON l.id = pl.location_id WHERE pl.farmer_id = :farmer ORDER BY pl.created_at DESC LIMIT 30', ['farmer' => $farmer['id']]);
workspace_open('Publish produce availability', 'listings');
?>
<section class="workspace-section farmer-publication-layout"><div class="workspace-section-header"><div><h2>Publish an accountable supply record</h2><p>Once published, this record becomes visible in the marketplace and alerts accounts whose default buying brief matches its terms.</p></div></div><?php if ($message = flash('success')): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><?php if ($message = flash('error')): ?><div class="alert alert-error"><?= e($message) ?></div><?php endif; ?><form class="attachment-form form-grid" method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="listing_action" value="publish"><div class="form-field"><label for="listing-title">Produce title</label><input id="listing-title" name="title" maxlength="160" required placeholder="Example: Pishin Grade A Apples"></div><div class="form-field"><label for="listing-category">Crop category</label><select id="listing-category" name="category_id" required><option value="">Choose a category</option><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>"><?= e($category['name']) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="listing-location">Origin location</label><select id="listing-location" name="location_id" required><option value="">Choose an origin</option><?php foreach ($locations as $location): ?><option value="<?= (int) $location['id'] ?>"><?= e($location['district'] . ' · ' . $location['tehsil'] . ' · ' . $location['area']) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="listing-grade">Grade</label><select id="listing-grade" name="grade" required><?php foreach (['A', 'B', 'C', 'Mixed'] as $grade): ?><option value="<?= $grade ?>">Grade <?= $grade ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="listing-quantity">Available quantity (kg)</label><input id="listing-quantity" name="quantity_available" type="number" min="1" step="0.01" required></div><div class="form-field"><label for="listing-price">Expected price (Rs./kg)</label><input id="listing-price" name="expected_price" type="number" min="1" step="0.01" required></div><div class="form-field"><label for="listing-minimum">Minimum order (kg)</label><input id="listing-minimum" name="minimum_order_quantity" type="number" min="1" step="0.01" required></div><div class="form-field"><label for="listing-harvest">Harvest date</label><input id="listing-harvest" name="harvest_date" type="date"></div><div class="form-field"><label for="listing-available">Available from</label><input id="listing-available" name="available_from" type="date"></div><div class="form-field"><label for="listing-description">Supply notes</label><textarea id="listing-description" name="description" rows="4" maxlength="1000" placeholder="Packing, maturity, collection, or trade terms buyers should know."></textarea></div><div class="form-actions"><span class="form-help">Publication alerts only use saved filters marked as a default buying brief.</span><button class="button button-primary" type="submit">Publish availability</button></div></form></section>
<section class="workspace-section"><div class="workspace-section-header"><div><h2>Your recent supply records</h2><p>Amend remaining quantity as orders progress, manage visibility, and export the activity trail for one of your records.</p></div></div><div class="data-table-wrap"><table class="data-table farmer-listing-table"><thead><tr><th>Produce</th><th>Origin</th><th>Grade</th><th>Available</th><th>Expected price</th><th>Status</th><th>Lifecycle and evidence</th></tr></thead><tbody><?php if ($listings === []): ?><tr><td colspan="7">No supply records have been published yet.</td></tr><?php else: foreach ($listings as $listing): ?><tr><td><?= e($listing['title']) ?><span class="table-muted"> · <?= e($listing['category_name']) ?></span></td><td><?= e($listing['district']) ?></td><td>Grade <?= e($listing['grade']) ?></td><td><form class="quantity-amendment-form" method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="listing_action" value="update_quantity"><input type="hidden" name="listing_id" value="<?= (int) $listing['id'] ?>"><input aria-label="Available quantity for <?= e($listing['title']) ?>" name="quantity_available" type="number" min="<?= e((string) $listing['minimum_order_quantity']) ?>" step="0.01" value="<?= e((string) $listing['quantity_available']) ?>"><span>kg</span><button class="text-action default-action" type="submit">Amend</button></form><span class="table-muted">Minimum order: <?= e((string) $listing['minimum_order_quantity']) ?> kg</span></td><td>Rs. <?= e(number_format((float) $listing['expected_price'], 0)) ?>/<?= e($listing['unit']) ?></td><td><span class="status-pill <?= e($listing['status']) ?>"><?= e(ucwords(str_replace('_', ' ', $listing['status']))) ?></span></td><td><div class="listing-status-actions"><?php if ($listing['status'] !== 'active'): ?><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="listing_action" value="update_status"><input type="hidden" name="listing_id" value="<?= (int) $listing['id'] ?>"><input type="hidden" name="status" value="active"><button class="text-action default-action" type="submit">Reactivate</button></form><?php endif; ?><?php if ($listing['status'] === 'active'): ?><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="listing_action" value="update_status"><input type="hidden" name="listing_id" value="<?= (int) $listing['id'] ?>"><input type="hidden" name="status" value="paused"><button class="text-action default-action" type="submit">Pause</button></form><?php endif; ?><?php if ($listing['status'] !== 'sold_out'): ?><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="listing_action" value="update_status"><input type="hidden" name="listing_id" value="<?= (int) $listing['id'] ?>"><input type="hidden" name="status" value="sold_out"><button class="text-action" type="submit">Mark sold out</button></form><?php endif; ?><a class="text-action default-action" href="<?= e(app_url('farmer/listing-activity-export.php?id=' . (int) $listing['id'])) ?>">Export activity CSV</a></div></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
<?php workspace_close(); ?>
